def _cross_version_field_changes(
    base_fields: dict[str, dict],
    target_fields: dict[str, dict],
) -> list[dict]:
    """Field-definition changes between two different schema versions.

    Only additions, removals, type changes and nullability changes are
    listed; an unchanged field (same type and nullability) never appears.
    The literals reuse the breaking-check/field-trajectory vocabulary
    (``added``, ``removed``, ``type_changed``, ``nullable_tightened``,
    ``nullable_loosened``); a field with several changes collapses into one
    entry, a type change winning over a nullability change. Entries are
    sorted by field name and each carries ``before``/``after`` definitions,
    null — never omitted — on the side where the field does not exist.
    """
    changes: list[dict] = []
    for name in sorted(set(base_fields) | set(target_fields)):
        before = base_fields.get(name)
        after = target_fields.get(name)
        if before == after:
            continue
        if before is None:
            kind = "added"
        elif after is None:
            kind = "removed"
        elif before["type"] != after["type"]:
            kind = "type_changed"
        elif after["nullable"] and not before["nullable"]:
            kind = "nullable_loosened"
        else:
            kind = "nullable_tightened"
        changes.append(
            {"field": name, "kind": kind, "before": before, "after": after}
        )
    return changes


def _project_rows_to_fields(
    rows: list[dict[str, Any]], common_fields: list[str]
) -> list[dict[str, Any]]:
    """Project rows onto fields defined on both versions.

    Only the named fields participate: every other stored key is dropped,
    and a field missing from a row is omitted (it never participates as a
    null). Projected objects are rebuilt in the common fields' sorted order,
    so the emitted rows are deterministic regardless of the stored object
    key order.
    """
    return [
        {name: row[name] for name in common_fields if name in row}
        for row in rows
    ]

